subscribeEvents('evidence.export.signed.v1', async (e) => {
  for (const blob_id of e.payload.bundle_blob_ids) {
    await applyWatermark({
      source_blob_id: blob_id,
      persona_id: e.payload.requested_by_persona_id,
      reason: `legal-export:${e.payload.export_id}`,
      visible: true, invisible: true,
    });
  }
});

